entries[449614] = { ["name"] = "Demonic Soul", ["text"] = "Demonology\nA demonic entity now inhabits your soul, allowing you to detect if a Soul Shard has a Succulent Soul when it's generated.\n\nA Succulent Soul empowers your next Hand of Gul'dan, increasing its damage by 60%, and unleashing your demonic soul to deal an additional (176.618% of Spell Power) Shadow damage.\n\nAffliction\nA demonic entity now inhabits your soul, allowing you to detect if a Soul Shard has a Succulent Soul when it's generated.\n\nA Succulent Soul empowers your next Malefic Rapture, increasing its damage by 20%, and unleashing your demonic soul to deal an additional (176.618% of Spell Power) Shadow damage." }
entries[449619] = { ["name"] = "Memory of Al'ar", ["text"] = "Arcane\nWhile under the effects of a casted Arcane Surge, you gain twice as many stacks of Mana Cascade.\n\nWhen your Arcane Phoenix expires, it empowers you, granting Arcane Soul for 2 sec, plus an additional 1.0 sec for each exceptional spell it had cast.\n\nArcane Soul :\nArcane Barrage grants Clearcasting and generates 4 Arcane Charges.\n\nEach cast of Arcane Barrage increases the damage of Arcane Barrage by 15%, up to 150%.\n\nFire\nWhile under the effects of a casted Combustion, you gain twice as many stacks of Mana Cascade.\n\nWhen your Arcane Phoenix expires, it empowers you, granting Hyperthermia for 2 sec, plus an additional 1.0 sec for each exceptional spell it had cast.\n\nHyperthermia :\nPyroblast and Flamestrike have no cast time, are guaranteed to critically strike, and increase the damage of Pyroblast and Flamestrike by 15%." }
entries[449620] = { ["name"] = "Necrolyte Teachings", ["text"] = "Affliction\nShadow Bolt and Drain Soul damage increased by 20%. Nightfall increases the damage of Shadow Bolt and Drain Soul by an additional 50%.\n\nDemonology\nShadow Bolt damage increased by 20%. Power Siphon increases the damage of Demonbolt by an additional 20%." }
